UPDATE quality_dispute
dispute_type = #{disputeType}, supplier_id = #{supplierId}, customer_id = #{customerId}, order_id = #{orderId}, claim_amount = #{claimAmount}, description = #{description}, evidence_urls = #{evidenceUrls}, handle_method = #{handleMethod}, finance_adjusted = #{financeAdjusted}, adjust_type = #{adjustType}, adjusted_amount = #{adjustedAmount}, adjusted_bill_no = #{adjustedBillNo}, adjust_remark = #{adjustRemark}, status = #{status}, handler_id = #{handlerId}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT qd.*,
       s.supplier_name, c.customer_name, u.real_name AS handler_name
FROM quality_dispute qd
LEFT JOIN supplier s ON qd.supplier_id = s.id
LEFT JOIN customer c ON qd.customer_id = c.id
LEFT JOIN sys_user u ON qd.handler_id = u.id

    AND qd.company_id = #{companyId}
    AND qd.dispute_type = #{disputeType}
    AND qd.status = #{status}

ORDER BY qd.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM quality_dispute

    AND company_id = #{companyId}
    AND dispute_type = #{disputeType}
    AND status = #{status}
